from typing import List, Dict, Any
from pydantic import BaseModel, Field
from fastapi import FastAPI, HTTPException
from enum import Enum

app = FastAPI()

class RequirementPriority(str, Enum):
    MUST_HAVE = 'must-have'
    SHOULD_HAVE = 'should-have'
    NICE_TO_HAVE = 'nice-to-have'

class Requirement(BaseModel):
    id: int = Field(..., gt=0)
    description: str
    priority: RequirementPriority
    category: str

class RequirementService:
    def __init__(self):
        self.requirements: List[Requirement] = []

    def add_requirement(self, requirement: Requirement) -> None:
        self.requirements.append(requirement)

    def get_requirements_by_priority(self, priority: RequirementPriority) -> List[Requirement]:
        return [req for req in self.requirements if req.priority == priority]

requirement_service = RequirementService()

@app.post('/requirements/')
def create_requirement(requirement: Requirement):
    requirement_service.add_requirement(requirement)
    return {'message': 'Requirement added successfully', 'id': requirement.id}

@app.get('/requirements/{priority}/')
def read_requirements_by_priority(priority: RequirementPriority):
    requirements = requirement_service.get_requirements_by_priority(priority)
    if not requirements:
        raise HTTPException(status_code=404, detail='No requirements found for this priority')
    return requirements
